CREATE OR REPLACE FUNCTION quality_postings_private.link_quality_posting(p_id uuid, p_order_id uuid DEFAULT NULL::uuid, p_delivery_id text DEFAULT NULL::text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE o public.quality_sampling_orders; BEGIN IF NOT quality_postings_private.can_link_postings() THEN RAISE EXCEPTION 'Not allowed to confirm posting links'; END IF; IF p_order_id IS NOT NULL THEN SELECT * INTO o FROM public.quality_sampling_orders WHERE id=p_order_id; IF NOT FOUND THEN RAISE EXCEPTION 'Sampling order not found'; END IF; IF p_delivery_id IS NOT NULL AND o.linked_store_record_id IS DISTINCT FROM p_delivery_id THEN RAISE EXCEPTION 'Delivery does not match the sampling order'; END IF; p_delivery_id:=coalesce(p_delivery_id,o.linked_store_record_id); END IF; IF p_delivery_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.coffee_records WHERE id=p_delivery_id) THEN RAISE EXCEPTION 'Delivery not found'; END IF;
UPDATE public.quality_analysis_postings SET linked_sampling_order_id=p_order_id,linked_delivery_id=p_delivery_id,link_method='admin_confirmed',linked_by=auth.uid(),linked_at=now(),updated_at=now() WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Posting not found'; END IF; RETURN jsonb_build_object('ok',true); END; $function$;